class Solution:
    def splitListToParts(self, head, k: int):
        length = 0
        curr = head
        while curr:
            length += 1
            curr = curr.next
        base_size = length // k
        extra = length % k
        result = []
        curr = head
        for i in range(k):
            result.append(curr)
            part_size = base_size + (1 if i < extra else 0)
            for _ in range(part_size - 1):
                if curr:
                    curr = curr.next
            if curr:
                nxt = curr.next
                curr.next = None
                curr = nxt
        return result

